// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Make the two sections left and right resizable"
// Changes: Two-column tab layout with a draggable divider (mouse/touch, arrow keys, double-click resets).
//          The left width is shared by all tabs and remembered in this browser; below lg the columns stack.

import { Children, useEffect, useRef, useState, type KeyboardEvent, type PointerEvent, type ReactNode } from 'react'
import { cx } from './ui'

const STORAGE_KEY = 'table-maker:split-left'
const DEFAULT_LEFT = 400
const MIN_LEFT = 280
const MIN_RIGHT = 360

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "make sure the layout stays fixed verticaly, make the left and right pane scrollable instead"
// Changes: Scrollable column of a fill layout (no bottom margin under the last panel, scrolling does not chain to the page).
const pane = 'lg:min-h-0 lg:overflow-y-auto lg:overscroll-contain lg:rounded-2xl lg:[&>*>*:last-child]:mb-0'

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "also teh definition and LL should have the horizonal resizing separate not linked to each other"
// Changes: Width is kept per layout id (Definícia and LL each have their own); tabs without an id share the default.
type Group = { width: number | null; loaded: boolean; listeners: Set<(w: number | null) => void> }
const groups = new Map<string, Group>()

function group(id: string) {
  let g = groups.get(id)
  if (!g) groups.set(id, (g = { width: null, loaded: false, listeners: new Set() }))
  return g
}

const storageKey = (id: string) => (id === 'default' ? STORAGE_KEY : `${STORAGE_KEY}:${id}`)

function readStored(id: string) {
  try {
    const n = Number(localStorage.getItem(storageKey(id)))
    return Number.isFinite(n) && n > 0 ? n : null
  } catch {
    return null
  }
}

function storeWidth(id: string, w: number | null) {
  const g = group(id)
  g.width = w
  g.listeners.forEach((fn) => fn(w))
  try {
    if (w === null) localStorage.removeItem(storageKey(id))
    else localStorage.setItem(storageKey(id), String(Math.round(w)))
  } catch {
    // Storage unavailable (private window etc.) – the width just is not remembered.
  }
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "also teh definition and LL should have the horizonal resizing separate not linked to each other"
// Changes: Optional id – layouts with different ids are resized independently.
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "make sure the layout stays fixed verticaly, make the left and right pane scrollable instead"
// Changes: fill – on wide screens the layout takes the parent's height and each column scrolls on its own.
export function SplitLayout({ id = 'default', fill = false, children }: { id?: string; fill?: boolean; children: ReactNode }) {
  const [left, right] = Children.toArray(children)
  const box = useRef<HTMLDivElement>(null)
  const [width, setWidth] = useState<number | null>(() => group(id).width)
  const [dragging, setDragging] = useState(false)
  const store = (w: number | null) => storeWidth(id, w)

  useEffect(() => {
    const g = group(id)
    if (!g.loaded) {
      g.width = readStored(id)
      g.loaded = true
    }
    setWidth(g.width)
    g.listeners.add(setWidth)
    return () => void g.listeners.delete(setWidth)
  }, [id])

  const clamp = (w: number) => {
    const total = box.current?.clientWidth ?? 1200
    // Same limit as the CSS min(): right column + divider + gaps (16px) must fit.
    return Math.round(Math.max(MIN_LEFT, Math.min(w, total - MIN_RIGHT - 16)))
  }
  const current = () => width ?? DEFAULT_LEFT

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return
    e.preventDefault()
    e.currentTarget.setPointerCapture(e.pointerId)
    setDragging(true)
  }
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    if (!dragging || !box.current) return
    store(clamp(e.clientX - box.current.getBoundingClientRect().left - 8))
  }
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const step = e.shiftKey ? 80 : 20
    if (e.key === 'ArrowLeft') store(clamp(current() - step))
    else if (e.key === 'ArrowRight') store(clamp(current() + step))
    else if (e.key === 'Home' || e.key === 'Enter') store(null)
    else return
    e.preventDefault()
  }

  return (
    <div
      ref={box}
      style={{ ['--split-left' as string]: `${width ?? DEFAULT_LEFT}px` }}
      className={cx(
        'grid items-start gap-4 lg:grid-cols-[min(var(--split-left),calc(100%-376px))_auto_minmax(0,1fr)] lg:gap-x-1',
        fill && 'lg:h-full lg:min-h-0 lg:grid-rows-[minmax(0,1fr)] lg:items-stretch',
        dragging && 'cursor-col-resize select-none',
      )}
    >
      <div className={cx('min-w-0', fill && pane)}>{left}</div>
      <div
        role="separator"
        aria-orientation="vertical"
        aria-label="Šírka ľavého stĺpca"
        aria-valuenow={width ?? DEFAULT_LEFT}
        tabIndex={0}
        title="Ťahaj pre zmenu šírky · dvojklik = pôvodná šírka"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={() => setDragging(false)}
        onPointerCancel={() => setDragging(false)}
        onDoubleClick={() => store(null)}
        onKeyDown={onKeyDown}
        className="group hidden w-3 cursor-col-resize touch-none self-stretch justify-center rounded-full outline-none focus-visible:bg-indigo-400/10 lg:flex"
      >
        <span
          className={cx(
            'w-px rounded-full transition-colors group-hover:w-0.5 group-hover:bg-indigo-400/60 group-focus-visible:w-0.5 group-focus-visible:bg-indigo-400/80',
            dragging ? 'w-0.5 bg-indigo-400' : 'bg-white/10',
          )}
        />
      </div>
      <div className={cx('min-w-0', fill && pane)}>{right}</div>
    </div>
  )
}
